"""The restaurant page the agent quotes hours, sittings and booking rules from.

Every fact on the page is read from restaurant.py when the function is called, through the module
object rather than names bound at import. A change to restaurant.py therefore changes the page, and
tests/test_knowledge.py fails until knowledge/restaurant.md is regenerated.
"""

from collections import Counter
from datetime import date, datetime, time, timedelta

from maitre_d import restaurant, speech

GENERATED_NOTICE = (
    "<!-- Generated by scripts/generate_knowledge.py from restaurant.py; "
    "must not be edited by hand. -->"
)

# last_seating() needs a date only so that time arithmetic can carry across the sitting length.
# No rule depends on which date it is.
_REFERENCE_DAY = date(2000, 1, 1)


def last_seating(service: restaurant.Service, party_size: int) -> time:
    """The latest start that timeslots accepts for this service and party size.

    timeslots has no function for this. It writes "closing time minus sitting length" inline, in
    candidate_starts() and _fits_service(). The page needs the value as text, so it is re-derived
    here, and tests/test_knowledge.py checks it against validate_start() so that the two cannot
    drift apart without a test failing.
    """
    closes = datetime.combine(_REFERENCE_DAY, service.closes)
    return (closes - restaurant.sitting_length(party_size)).time()


def _minutes(length: timedelta) -> int:
    return length // timedelta(minutes=1)


def _describe_services(services: tuple[restaurant.Service, ...]) -> str:
    if not services:
        return "closed"
    return ", ".join(f"{s.name} {s.opens:%H:%M}-{s.closes:%H:%M}" for s in services)


def _weekday_runs() -> list[tuple[int, int, tuple[restaurant.Service, ...]]]:
    """Runs of consecutive weekdays with identical services, as (first, last, services).

    Grouping keeps the page to "Tuesday to Sunday" rather than one line per day, and comparing the
    service tuples means a change to one day splits the run instead of being hidden by it.
    """
    runs: list[tuple[int, int, tuple[restaurant.Service, ...]]] = []
    for weekday in range(7):
        services = restaurant.SERVICES_BY_WEEKDAY[weekday]
        if runs and runs[-1][2] == services:
            first, _, _ = runs[-1]
            runs[-1] = (first, weekday, services)
        else:
            runs.append((weekday, weekday, services))
    return runs


def _hours_lines() -> list[str]:
    lines: list[str] = []
    for first, last, services in _weekday_runs():
        if first == last:
            label = speech.WEEKDAYS[first]
        else:
            label = f"{speech.WEEKDAYS[first]} to {speech.WEEKDAYS[last]}"
        lines.append(f"- {label}: {_describe_services(services)}")
    return lines


def _closed_dates_lines() -> list[str]:
    dates = [
        f"{day} {speech.MONTHS[month - 1]}" for month, day in sorted(restaurant.CLOSED_DAYS_OF_YEAR)
    ]
    if not dates:
        return []
    listed = speech.spoken_list(dates, "and")
    return [f"Closed every year on these dates, whatever the weekday: {listed}."]


def _services_in_week() -> tuple[restaurant.Service, ...]:
    """Each distinct service once, in the order the week lists them, for the seating columns."""
    return tuple(
        dict.fromkeys(
            service for weekday in range(7) for service in restaurant.SERVICES_BY_WEEKDAY[weekday]
        )
    )


def _sitting_bands() -> list[tuple[int, int]]:
    """Runs of party sizes that share a sitting length, as (smallest, largest) pairs."""
    bands: list[tuple[int, int]] = []
    for size in range(1, restaurant.MAX_PARTY_SIZE + 1):
        if bands and restaurant.sitting_length(bands[-1][0]) == restaurant.sitting_length(size):
            bands[-1] = (bands[-1][0], size)
        else:
            bands.append((size, size))
    return bands


def _seating_lines(services: tuple[restaurant.Service, ...]) -> list[str]:
    lines: list[str] = []
    for smallest, largest in _sitting_bands():
        sitting = _minutes(restaurant.sitting_length(smallest))
        seatings = ", ".join(
            f"{service.name} {last_seating(service, smallest):%H:%M}" for service in services
        )
        size = str(smallest) if smallest == largest else f"{smallest} to {largest}"
        lines.append(f"| {size} | {sitting} minutes | {seatings} |")
    return lines


def _table_lines() -> list[str]:
    counts = Counter(table.seats for table in restaurant.TABLES)
    lines: list[str] = []
    for seats in sorted(counts):
        count = counts[seats]
        noun = "table" if count == 1 else "tables"
        lines.append(f"- {count} {noun} seating {seats}")
    return lines


def render_restaurant_page() -> str:
    services = _services_in_week()
    max_party = restaurant.MAX_PARTY_SIZE
    lines = [
        GENERATED_NOTICE,
        "",
        f"# {restaurant.NAME}: hours, location and booking rules",
        "",
        f"Address: {restaurant.ADDRESS}",
        "",
        "## Opening hours",
        "",
        "All times are London time, on a 24-hour clock.",
        "",
        *_hours_lines(),
        "",
        *_closed_dates_lines(),
        "",
        "## Last seating",
        "",
        "A booking holds its table for the whole sitting, so the sitting must finish by closing",
        "time. The last seating is closing time minus the sitting length: the latest a party can",
        "be seated.",
        "",
        "| Party size | Sitting | Last seating |",
        "|---|---|---|",
        *_seating_lines(services),
        "",
        "## Tables and party size",
        "",
        *_table_lines(),
        "",
        f"Tables are never combined. The largest table seats {max_party}, so a party of more than "
        f"{max_party} cannot be booked by phone. The agent takes a message for the events team "
        "instead.",
        "",
        "## Booking rules",
        "",
        f"- Bookings can be made from {_minutes(restaurant.MIN_NOTICE)} minutes from now, up to "
        f"{restaurant.BOOKING_HORIZON.days} days ahead.",
        f"- Start times fall every {restaurant.SLOT_MINUTES} minutes.",
        "- Changing or cancelling a booking needs the booker's name and phone number.",
    ]
    return "\n".join(lines) + "\n"
